class TestGitLog(unittest.TestCase):
    def test_round_trip_and_idempotent(self):
        repo = tempfile.mkdtemp(prefix="grpc-dc-eventbus-")
        broker = eventbus.EventBusBroker()
        events = [
            broker.publish_event([eventbus.tag_string(Tag.TOPIC, "orders")], b"o1", "test"),
            broker.publish_event([eventbus.tag_string(Tag.TOPIC, "other")], b"x1", "test"),
            broker.publish_event([eventbus.tag_string(Tag.TOPIC, "orders")], b"o2", "test"),
        ]
        head1 = eventbus_git.export_events(repo, events)
        count = subprocess.run(
            ["git", "-C", repo, "rev-list", "--count", "grpc-dc-events"],
            stdout=subprocess.PIPE,
            check=True,
        ).stdout.decode().strip()
        self.assertEqual(count, "3")
        self.assertEqual(eventbus_git.export_events(repo, events), head1)
        all_events = eventbus_git.import_events(repo)
        self.assertEqual([e.seq for e in all_events], [1, 2, 3])
        self.assertEqual([e.payload for e in all_events], [b"o1", b"x1", b"o2"])
        self.assertTrue(all(e.publisher_id == "test" for e in all_events))
        orders = eventbus_git.import_events(repo, filter_tags=[eventbus.tag_string(Tag.TOPIC, "orders")])
        self.assertEqual([e.seq for e in orders], [1, 3])
        window = eventbus_git.import_events(repo, from_seq=1, to_seq=2)
        self.assertEqual([e.seq for e in window], [2])


